import{_ as e,c as r,o as i,a3 as t}from"./chunks/framework.BusRvirq.js";const m=JSON.parse('{"title":"기술 용어 사전","description":"SyncETA 플랫폼의 핵심 개념, 레코드, 시나리오, 컬렉션, 스토리, MCP, Self-Healing 등 주요 기술 용어를 정의합니다.","frontmatter":{"title":"기술 용어 사전","description":"SyncETA 플랫폼의 핵심 개념, 레코드, 시나리오, 컬렉션, 스토리, MCP, Self-Healing 등 주요 기술 용어를 정의합니다.","head":[["meta",{"name":"keywords","content":"SyncETA, 기술 용어, 레코드, 시나리오, 컬렉션, 스토리, 데이터셋, MCP, Self-Healing, Visual Regression"}],["meta",{"property":"og:title","content":"기술 용어 사전 | SyncETA"}],["meta",{"property":"og:description","content":"SyncETA 플랫폼의 주요 용어 및 개념 정의입니다."}],["link",{"rel":"canonical","href":"https://doc.empasy.com/synceta/glossary.html"}]],"sort":1200},"headers":[],"relativePath":"synceta/glossary.md","filePath":"ko/synceta/glossary.md","lastUpdated":1787441310000}'),n={name:"synceta/glossary.md"};function l(o,a,s,h,c,p){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="기술-용어-사전" tabindex="-1">기술 용어 사전 <a class="header-anchor" href="#기술-용어-사전" aria-label="Permalink to “기술 용어 사전”">​</a></h1><p>SyncETA 플랫폼에서 사용되는 핵심 개념과 기술 용어에 대한 정의입니다.</p><hr><h3 id="record-레코드" tabindex="-1">Record (레코드) <a class="header-anchor" href="#record-레코드" aria-label="Permalink to “Record (레코드)”">​</a></h3><p>사용자의 브라우저 이벤트 및 DOM 정보를 기록하는 최소 실행 단위입니다. 클릭, 키보드 입력, 스크롤, 탭 전환 등 사용자의 조작을 URL, XPath, CSS Selector, 태그 속성 정보와 함께 실시간으로 캡처하여 저장합니다.</p><h3 id="scenario-시나리오" tabindex="-1">Scenario (시나리오) <a class="header-anchor" href="#scenario-시나리오" aria-label="Permalink to “Scenario (시나리오)”">​</a></h3><p>일련의 레코드들을 특정 비즈니스 흐름(예: 로그인, 상품 검색, 결제 등)에 맞추어 순차적으로 구성한 기본 테스트 케이스 단위입니다. 대기 조건, 검증 조건, 실패 복구 스크립트를 포함할 수 있습니다.</p><h3 id="collection-컬렉션" tabindex="-1">Collection (컬렉션) <a class="header-anchor" href="#collection-컬렉션" aria-label="Permalink to “Collection (컬렉션)”">​</a></h3><p>여러 개의 독립된 시나리오들을 그룹화하여 하나의 테스트 스위트 단위로 순차 또는 병렬 실행하는 묶음 실행 기능입니다.</p><h3 id="story-스토리" tabindex="-1">Story (스토리) <a class="header-anchor" href="#story-스토리" aria-label="Permalink to “Story (스토리)”">​</a></h3><p>플로우차트(Flowchart) 캔버스 인터페이스를 통해 여러 시나리오를 조건부로 연결하고, 단일 브라우저 세션에서 세션 상태(쿠키, 로그인)를 유지하며 연속 실행하는 상위 통합 워크플로우입니다.</p><h3 id="data-set-데이터셋" tabindex="-1">Data Set (데이터셋) <a class="header-anchor" href="#data-set-데이터셋" aria-label="Permalink to “Data Set (데이터셋)”">​</a></h3><p>시나리오에 정의된 입력 변수에 매핑할 테스트 데이터를 스프레드시트(Key-Value) 형태로 관리하는 기능입니다. Excel 파일 Import/Export를 지원하여 Data-Driven Testing을 수행합니다.</p><h3 id="playwright-mcp" tabindex="-1">Playwright MCP <a class="header-anchor" href="#playwright-mcp" aria-label="Permalink to “Playwright MCP”">​</a></h3><p>Model Context Protocol(MCP) 표준을 준수하여 Playwright 브라우저 인스턴스를 원격으로 제어하는 분산 테스트 실행 엔진입니다. Chromium, Firefox, WebKit 멀티 브라우저 병렬 구동을 지원합니다.</p><h3 id="visual-regression-ai-시각적-회귀-분석" tabindex="-1">Visual Regression AI (시각적 회귀 분석) <a class="header-anchor" href="#visual-regression-ai-시각적-회귀-분석" aria-label="Permalink to “Visual Regression AI (시각적 회귀 분석)”">​</a></h3><p>픽셀 단위 단순 비교의 한계를 극복하기 위해 비전 모델을 활용하여 화면 내 컴포넌트 겹침(Overlapping), 텍스트 잘림(Clipping), 레이아웃 깨짐 현상을 사용자 인지 관점에서 분석하는 기능입니다.</p><h3 id="self-healing-자가-치유" tabindex="-1">Self-Healing (자가 치유) <a class="header-anchor" href="#self-healing-자가-치유" aria-label="Permalink to “Self-Healing (자가 치유)”">​</a></h3><p>웹 애플리케이션의 배포로 인해 기존 DOM 식별자(XPath/CSS Selector)가 변경되었을 때, 비전 모델과 DOM 트리를 분석하여 새로운 대체 선택자 후보를 산출하고 승인 큐에 전달하는 기능입니다.</p><h3 id="human-in-the-loop-거버넌스" tabindex="-1">Human-in-the-Loop 거버넌스 <a class="header-anchor" href="#human-in-the-loop-거버넌스" aria-label="Permalink to “Human-in-the-Loop 거버넌스”">​</a></h3><p>AI가 생성한 테스트 케이스나 자가 치유 선택자를 시스템에 자동 반영하기 전, QA 엔지니어 및 관리자의 명시적 검토와 승인을 거치도록 하는 품질 관리 원칙입니다.</p><h3 id="air-gapped-on-premise-배포" tabindex="-1">Air-Gapped / On-Premise 배포 <a class="header-anchor" href="#air-gapped-on-premise-배포" aria-label="Permalink to “Air-Gapped / On-Premise 배포”">​</a></h3><p>외부 인터넷 통신이 차단된 사내 폐쇄망 환경에서도 로컬 오픈소스 Vision/LLM 엔진(vLLM 등)과 결합하여 독립적으로 구동 가능한 엔터프라이즈 배포 방식입니다.</p>',23)])])}const g=e(n,[["render",l]]);export{m as __pageData,g as default};
